    wire i2_win0, i2_win1, i2_win2, i2_win3, i2_win4, i2_win5;
    wire i3_win0, i3_win1, i3_win2, i3_win3, i3_win4, i3_win5;
    wire [127:0] i0_oq0, i0_oq1, i0_oq2, i0_oq3, i0_oq4, i0_oq5;
    wire [127:0] i1_oq0, i1_oq1, i1_oq2, i1_oq3, i1_oq4, i1_oq5;
    wire [127:0] i2_oq0, i2_oq1, i2_oq2, i2_oq3, i2_oq4, i2_oq5;
    wire [127:0] i3_oq0, i3_oq1, i3_oq2, i3_oq3, i3_oq4, i3_oq5;
    wire i0_pfv0, i0_pfv1, i0_pfv2, i0_pfv3, i0_pfv4, i0_pfv5;
    wire i1_pfv0, i1_pfv1, i1_pfv2, i1_pfv3, i1_pfv4, i1_pfv5;
    wire i2_pfv0, i2_pfv1, i2_pfv2, i2_pfv3, i2_pfv4, i2_pfv5;
    wire i3_pfv0, i3_pfv1, i3_pfv2, i3_pfv3, i3_pfv4, i3_pfv5;
    wire [127:0] i0_pfw0, i0_pfw1, i0_pfw2, i0_pfw3, i0_pfw4, i0_pfw5;
    wire [127:0] i1_pfw0, i1_pfw1, i1_pfw2, i1_pfw3, i1_pfw4, i1_pfw5;
    wire [127:0] i2_pfw0, i2_pfw1, i2_pfw2, i2_pfw3, i2_pfw4, i2_pfw5;
    wire [127:0] i3_pfw0, i3_pfw1, i3_pfw2, i3_pfw3, i3_pfw4, i3_pfw5;

    wire cred_avail = (spool != 4'd0);

    wire want0 = en[0] && (i0_pool != 4'd0) && ((req[5:0]   & ~i0_held) != 6'd0);
    wire want1 = en[1] && (i1_pool != 4'd0) && ((req[11:6]  & ~i1_held) != 6'd0);
    wire want2 = en[2] && (i2_pool != 4'd0) && ((req[17:12] & ~i2_held) != 6'd0);
    wire want3 = en[3] && (i3_pool != 4'd0) && ((req[23:18] & ~i3_held) != 6'd0);

    wire take0 = cred_avail && want0;
    wire take1 = cred_avail && want1 && !want0;
    wire take2 = cred_avail && want2 && !want0 && !want1;
    wire take3 = cred_avail && want3 && !want0 && !want1 && !want2;
    wire any_take = take0 | take1 | take2 | take3;

    wire [5:0] q0 = take0 ? req[5:0]   : 6'd0;
    wire [5:0] q1 = take1 ? req[11:6]  : 6'd0;
    wire [5:0] q2 = take2 ? req[17:12] : 6'd0;
    wire [5:0] q3 = take3 ? req[23:18] : 6'd0;

    wire give0 = en[0] && ((rel[5:0]   & i0_held) != 6'd0);
    wire give1 = en[1] && ((rel[11:6]  & i1_held) != 6'd0);
    wire give2 = en[2] && ((rel[17:12] & i2_held) != 6'd0);
    wire give3 = en[3] && ((rel[23:18] & i3_held) != 6'd0);
    wire [2:0] n_give = {2'b0, give0} + {2'b0, give1} + {2'b0, give2} + {2'b0, give3};

    wire [2:0] t0 = {2'b0, i0_h0} + {2'b0, i0_h1} + {2'b0, i0_h2} + {2'b0, i0_h3} + {2'b0, i0_h4} + {2'b0, i0_h5};
    wire [2:0] t1 = {2'b0, i1_h0} + {2'b0, i1_h1} + {2'b0, i1_h2} + {2'b0, i1_h3} + {2'b0, i1_h4} + {2'b0, i1_h5};
    wire [2:0] t2 = {2'b0, i2_h0} + {2'b0, i2_h1} + {2'b0, i2_h2} + {2'b0, i2_h3} + {2'b0, i2_h4} + {2'b0, i2_h5};
    wire [2:0] t3 = {2'b0, i3_h0} + {2'b0, i3_h1} + {2'b0, i3_h2} + {2'b0, i3_h3} + {2'b0, i3_h4} + {2'b0, i3_h5};

    xbar_route_pool p0 (.clk(clk), .rst_n(rst_n), .en(en[0]), .req(q0), .rel(rel[5:0]),
        .pool_o(i0_pool), .held_o(i0_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i0_cnt0), .cnt1_o(i0_cnt1), .cnt2_o(i0_cnt2), .cnt3_o(i0_cnt3), .cnt4_o(i0_cnt4), .cnt5_o(i0_cnt5),
        .h0_o(i0_h0), .h1_o(i0_h1), .h2_o(i0_h2), .h3_o(i0_h3), .h4_o(i0_h4), .h5_o(i0_h5),
        .oq0_o(i0_oq0), .oq1_o(i0_oq1), .oq2_o(i0_oq2), .oq3_o(i0_oq3), .oq4_o(i0_oq4), .oq5_o(i0_oq5),
        .pfv0_o(i0_pfv0), .pfv1_o(i0_pfv1), .pfv2_o(i0_pfv2), .pfv3_o(i0_pfv3), .pfv4_o(i0_pfv4), .pfv5_o(i0_pfv5),
        .pfw0_o(i0_pfw0), .pfw1_o(i0_pfw1), .pfw2_o(i0_pfw2), .pfw3_o(i0_pfw3), .pfw4_o(i0_pfw4), .pfw5_o(i0_pfw5),
        .pool_obs(),
        .rdp0_o(i0_rdp0), .rdp1_o(i0_rdp1), .rdp2_o(i0_rdp2), .rdp3_o(i0_rdp3), .rdp4_o(i0_rdp4), .rdp5_o(i0_rdp5),
        .win0_o(i0_win0), .win1_o(i0_win1), .win2_o(i0_win2), .win3_o(i0_win3), .win4_o(i0_win4), .win5_o(i0_win5));

    xbar_route_pool p1 (.clk(clk), .rst_n(rst_n), .en(en[1]), .req(q1), .rel(rel[11:6]),
        .pool_o(i1_pool), .held_o(i1_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i1_cnt0), .cnt1_o(i1_cnt1), .cnt2_o(i1_cnt2), .cnt3_o(i1_cnt3), .cnt4_o(i1_cnt4), .cnt5_o(i1_cnt5),
        .h0_o(i1_h0), .h1_o(i1_h1), .h2_o(i1_h2), .h3_o(i1_h3), .h4_o(i1_h4), .h5_o(i1_h5),
        .oq0_o(i1_oq0), .oq1_o(i1_oq1), .oq2_o(i1_oq2), .oq3_o(i1_oq3), .oq4_o(i1_oq4), .oq5_o(i1_oq5),
        .pfv0_o(i1_pfv0), .pfv1_o(i1_pfv1), .pfv2_o(i1_pfv2), .pfv3_o(i1_pfv3), .pfv4_o(i1_pfv4), .pfv5_o(i1_pfv5),
        .pfw0_o(i1_pfw0), .pfw1_o(i1_pfw1), .pfw2_o(i1_pfw2), .pfw3_o(i1_pfw3), .pfw4_o(i1_pfw4), .pfw5_o(i1_pfw5),
        .pool_obs(),
        .rdp0_o(i1_rdp0), .rdp1_o(i1_rdp1), .rdp2_o(i1_rdp2), .rdp3_o(i1_rdp3), .rdp4_o(i1_rdp4), .rdp5_o(i1_rdp5),
        .win0_o(i1_win0), .win1_o(i1_win1), .win2_o(i1_win2), .win3_o(i1_win3), .win4_o(i1_win4), .win5_o(i1_win5));

    xbar_route_pool p2 (.clk(clk), .rst_n(rst_n), .en(en[2]), .req(q2), .rel(rel[17:12]),
        .pool_o(i2_pool), .held_o(i2_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i2_cnt0), .cnt1_o(i2_cnt1), .cnt2_o(i2_cnt2), .cnt3_o(i2_cnt3), .cnt4_o(i2_cnt4), .cnt5_o(i2_cnt5),
        .h0_o(i2_h0), .h1_o(i2_h1), .h2_o(i2_h2), .h3_o(i2_h3), .h4_o(i2_h4), .h5_o(i2_h5),
        .oq0_o(i2_oq0), .oq1_o(i2_oq1), .oq2_o(i2_oq2), .oq3_o(i2_oq3), .oq4_o(i2_oq4), .oq5_o(i2_oq5),
        .pfv0_o(i2_pfv0), .pfv1_o(i2_pfv1), .pfv2_o(i2_pfv2), .pfv3_o(i2_pfv3), .pfv4_o(i2_pfv4), .pfv5_o(i2_pfv5),
        .pfw0_o(i2_pfw0), .pfw1_o(i2_pfw1), .pfw2_o(i2_pfw2), .pfw3_o(i2_pfw3), .pfw4_o(i2_pfw4), .pfw5_o(i2_pfw5),
        .pool_obs(),
        .rdp0_o(i2_rdp0), .rdp1_o(i2_rdp1), .rdp2_o(i2_rdp2), .rdp3_o(i2_rdp3), .rdp4_o(i2_rdp4), .rdp5_o(i2_rdp5),
        .win0_o(i2_win0), .win1_o(i2_win1), .win2_o(i2_win2), .win3_o(i2_win3), .win4_o(i2_win4), .win5_o(i2_win5));

    xbar_route_pool p3 (.clk(clk), .rst_n(rst_n), .en(en[3]), .req(q3), .rel(rel[23:18]),
        .pool_o(i3_pool), .held_o(i3_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i3_cnt0), .cnt1_o(i3_cnt1), .cnt2_o(i3_cnt2), .cnt3_o(i3_cnt3), .cnt4_o(i3_cnt4), .cnt5_o(i3_cnt5),
        .h0_o(i3_h0), .h1_o(i3_h1), .h2_o(i3_h2), .h3_o(i3_h3), .h4_o(i3_h4), .h5_o(i3_h5),
        .oq0_o(i3_oq0), .oq1_o(i3_oq1), .oq2_o(i3_oq2), .oq3_o(i3_oq3), .oq4_o(i3_oq4), .oq5_o(i3_oq5),
        .pfv0_o(i3_pfv0), .pfv1_o(i3_pfv1), .pfv2_o(i3_pfv2), .pfv3_o(i3_pfv3), .pfv4_o(i3_pfv4), .pfv5_o(i3_pfv5),
        .pfw0_o(i3_pfw0), .pfw1_o(i3_pfw1), .pfw2_o(i3_pfw2), .pfw3_o(i3_pfw3), .pfw4_o(i3_pfw4), .pfw5_o(i3_pfw5),
        .pool_obs(),
        .rdp0_o(i3_rdp0), .rdp1_o(i3_rdp1), .rdp2_o(i3_rdp2), .rdp3_o(i3_rdp3), .rdp4_o(i3_rdp4), .rdp5_o(i3_rdp5),
        .win0_o(i3_win0), .win1_o(i3_win1), .win2_o(i3_win2), .win3_o(i3_win3), .win4_o(i3_win4), .win5_o(i3_win5));

    always @(posedge clk) begin
        if (!rst_n) begin
            spool <= TOTAL;
        end else begin
            spool <= spool - {3'b0, any_take} + {1'b0, n_give};
        end
    end

    always @(posedge clk)
        assert (spool <= TOTAL);

    assign spool_o = spool;
    assign ipool_o = {i3_pool, i2_pool, i1_pool, i0_pool};
    assign busy_o  = {(i3_held != 6'd0), (i2_held != 6'd0), (i1_held != 6'd0), (i0_held != 6'd0)};
endmodule

module atpg_pattern_buf #(
    parameter W = 128,
    parameter DEPTH = 24
) (
    input  wire                           clk,
    input  wire                           rst,
    input  wire                           in_valid,
    output wire                           in_ready,
    input  wire [W-1:0]                   in_data,
    output wire                           out_valid,
    input  wire                           out_ready,
    output wire [W-1:0]                   out_data,
    input  wire                           load_limit,
    input  wire [$clog2(DEPTH+1)-1:0]     limit_in
);
    localparam CW = $clog2(DEPTH+1);
    localparam PW = $clog2(DEPTH);

    // occupancy held in a DICE-style quadruple of interlocked storage nodes
    reg [CW-1:0] n0, n1, n2, n3;
    reg [CW-1:0] limit;
    reg [PW-1:0] wptr, rptr;
    reg          armed;
    reg [W-1:0]  mem [0:DEPTH-1];

    integer i;
    initial begin
        n0 = 0; n1 = 0; n2 = 0; n3 = 0;
        limit = DEPTH;
        wptr = 0; rptr = 0;
        armed = 1'b0;
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {W{1'b0}};
    end

    // interlock restoration: a node is overridden when its two neighbours agree
    wire [CW-1:0] b0 = (n1 == n3) ? n1 : n0;
    wire [CW-1:0] b1 = (n2 == n0) ? n2 : n1;
    wire [CW-1:0] b2 = (n3 == n1) ? n3 : n2;
    wire [CW-1:0] b3 = (n0 == n2) ? n0 : n3;

    wire [CW-1:0] cap = (limit > DEPTH) ? DEPTH[CW-1:0] : limit;

    assign in_ready  = (n0 < cap);
    assign out_valid = (n0 != {CW{1'b0}});
    assign out_data  = mem[rptr];

    wire do_push = in_valid && in_ready;
    wire do_pop  = out_valid && out_ready;

    wire [PW-1:0] wptr_nx = (wptr == DEPTH-1) ? {PW{1'b0}} : wptr + 1'b1;
    wire [PW-1:0] rptr_nx = (rptr == DEPTH-1) ? {PW{1'b0}} : rptr + 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            n0 <= 0; n1 <= 0; n2 <= 0; n3 <= 0;
            wptr <= 0; rptr <= 0;
            limit <= limit_in;
        end else begin
            if (load_limit) limit <= limit_in;
            if (do_push) begin
                mem[wptr] <= in_data;
                wptr <= wptr_nx;
            end
            if (do_pop) rptr <= rptr_nx;
            if (do_push != do_pop) begin
                n0 <= do_push ? b0 + 1'b1 : b0 - 1'b1;
                n1 <= do_push ? b1 + 1'b1 : b1 - 1'b1;
                n2 <= do_push ? b2 + 1'b1 : b2 - 1'b1;
                n3 <= do_push ? b3 + 1'b1 : b3 - 1'b1;
            end
        end
    end

    // sticky scope: armed by the first accepted pattern, never cleared
    always @(posedge clk)
        if (do_push) armed <= 1'b1;

    assert property (!armed || n0 <= DEPTH);
endmodule

module scan_unload_chain (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire [31:0] scan_in,
    input  wire [31:0] func_d,
    output wire [31:0] scan_out,
    output wire        busy_o
);
    // 32-entry scan chain of 32-bit scan flip-flops
    reg [31:0] chain [0:31];
    reg        busy     = 1'b0;
    reg [31:0] shifted  = 32'd0;
    reg [31:0] deadline = 32'd0;
    integer i;
    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) chain[k] = 32'd0;
    end

    assign scan_out = chain[31];
    assign busy_o   = busy;

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            shifted  <= 32'd0;
            deadline <= 32'd0;
        end else if (ce) begin
            if (busy) begin
                // test mode: scan mux selects the previous flop
                for (i = 31; i > 0; i = i - 1)
                    chain[i] <= chain[i-1];
                chain[0] <= scan_in;
                shifted  <= shifted + 32'd1;
                deadline <= deadline - 32'd1;
                if (shifted == 32'd31)
                    busy <= 1'b0;
            end else if (req) begin
                // accept unload request: countdown guarantees completion in 32 shifts
                busy     <= 1'b1;
                shifted  <= 32'd0;
                deadline <= 32'd32;
            end else begin
                // functional mode: scan mux selects functional data
                for (i = 0; i < 32; i = i + 1)
                    chain[i] <= chain[i] ^ func_d;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy))
            assert ($past(deadline) != 32'd0);
endmodule

module stepper_seq (
    input wire clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_arm,
    input wire i_start,
    input wire [7:0] i_rate,
    input wire i_wr,
    input wire [2:0] i_waddr,
    input wire [127:0] i_wdata,
    output wire [127:0] o_coil,
    output wire o_done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0] fsm = S_IDLE;
    reg win = 1'b0;
    reg arm_seen = 1'b0;
    reg start_seen = 1'b0;
    reg [2:0] phase = 3'd0;
    reg [7:0] div = 8'd0;
    reg [7:0] rate = 8'd0;

    reg [127:0] pat [0:7];
    integer k;
    initial for (k = 0; k < 8; k = k + 1) pat[k] = 128'd1 << (k * 16);

    always @(posedge clk)
        if (i_ce && i_wr && !win)
            pat[i_waddr] <= i_wdata;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!win) begin
                if (i_open) begin
                    win <= 1'b1;
                    fsm <= S_IDLE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    phase <= 3'd0;
                    div <= 8'd0;
                end
            end else if (i_close) begin
                win <= 1'b0;
            end else begin
                case (fsm)
                    S_IDLE: if (i_arm) begin
                        fsm <= S_ARMED;
                        arm_seen <= 1'b1;
                        rate <= i_rate;
                    end
                    S_ARMED: if (i_start) begin
                        fsm <= S_RUN;
                        start_seen <= 1'b1;
                        div <= 8'd0;
                    end
                    S_RUN: begin
                        if (div == rate) begin
                            div <= 8'd0;
                            phase <= phase + 3'd1;
                            if (phase == 3'd7)
                                fsm <= S_DONE;
                        end else begin
                            div <= div + 8'd1;
                        end
                    end
                    default: if (i_arm) begin
                        fsm <= S_ARMED;
                        start_seen <= 1'b0;
                        rate <= i_rate;
                    end
                endcase
            end
        end
    end

    assign o_coil = pat[phase];
    assign o_done = (fsm == S_DONE);

    always @(*) if (win && fsm == S_DONE) assert (start_seen);
    always @(*) if (win && start_seen) assert (arm_seen);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps <= steps + 3'd1;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       steps   <= steps + 3'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       steps     <= steps + 3'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                       steps <= steps + 3'd1;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module bitserial_alu (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       arm,
    input  wire       start,
    input  wire       ack,
    input  wire [1:0] op,
    input  wire [7:0] a_in,
    input  wire [7:0] b_in,
    output wire [7:0] result,
    output wire       done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase      = 2'd0;
    reg [7:0] cnt        = 8'd0;
    reg       seen_arm   = 1'b0;
    reg       seen_start = 1'b0;
    reg [1:0] op_r       = 2'd0;
    reg [7:0] opa        = 8'd0;
    reg [7:0] opb        = 8'd0;
    reg [7:0] res        = 8'd0;
    reg       carry      = 1'b0;

    wire abit = opa[0];
    wire bbit = (op_r == 2'd1) ? ~opb[0] : opb[0];
    wire sbit = abit ^ bbit ^ carry;
    wire cout = (abit & bbit) | (abit & carry) | (bbit & carry);
    wire fbit = (op_r == 2'd2) ? (abit & opb[0]) :
                (op_r == 2'd3) ? (abit ^ opb[0]) : sbit;

    assign result = res;
    assign done   = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            cnt        <= 8'd0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            carry      <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase      <= ARMED;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        op_r       <= op;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase      <= RUN;
                        seen_start <= 1'b1;
                        cnt        <= 8'd0;
                        opa        <= a_in;
                        opb        <= b_in;
                        res        <= 8'd0;
                        carry      <= (op_r == 2'd1);
                    end
                end
                RUN: begin
                    res   <= {fbit, res[7:1]};
                    opa   <= {1'b0, opa[7:1]};
                    opb   <= {1'b0, opb[7:1]};
                    carry <= (op_r[1] == 1'b0) ? cout : 1'b0;
                    if (cnt == 8'd7) begin
                        phase <= DONE;
                        cnt   <= 8'd8;
                    end else begin
                        cnt <= cnt + 8'd1;
                    end
                end
                DONE: begin
                    if (ack) begin
                        phase      <= IDLE;
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
            endcase
        end
    end

    assert property (phase != 2'd3 || (seen_arm && seen_start));
endmodule

module therm_totalizer (
    input  wire        clk,
    input  wire        en,
    input  wire [63:0] therm,
    output wire [63:0] out
);
    // popcount encoder
    reg [6:0] cnt;
    integer k;
    always @(*) begin
        cnt = 7'd0;
        for (k = 0; k < 64; k = k + 1)
            cnt = cnt + {6'd0, therm[k]};
    end

    wire [63:0] addend = {57'd0, cnt};

    reg [63:0] rca_sum;
    reg [63:0] cla_sum;
    reg        armed;
    reg        pv;
    initial rca_sum = 64'd0;
    initial cla_sum = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    // ripple-carry adder
    wire [64:0] rc;
    wire [63:0] rca_next;
    assign rc[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 64; i = i + 1) begin : g_rca
            assign rca_next[i] = rca_sum[i] ^ addend[i] ^ rc[i];
            assign rc[i+1] = (rca_sum[i] & addend[i]) | (rc[i] & (rca_sum[i] ^ addend[i]));
        end
    endgenerate

    // carry-lookahead adder, 4-bit groups
    wire [63:0] cg = cla_sum & addend;
    wire [63:0] cp = cla_sum ^ addend;
    wire [63:0] cc;
    wire [16:0] gcarry;
    wire [63:0] cla_next;
    assign gcarry[0] = 1'b0;
    genvar j;
    generate
        for (j = 0; j < 16; j = j + 1) begin : g_cla
            wire g0 = cg[4*j];   wire p0 = cp[4*j];
            wire g1 = cg[4*j+1]; wire p1 = cp[4*j+1];
            wire g2 = cg[4*j+2]; wire p2 = cp[4*j+2];
            wire g3 = cg[4*j+3]; wire p3 = cp[4*j+3];
            wire c0 = gcarry[j];
            assign cc[4*j]   = c0;
            assign cc[4*j+1] = g0 | (p0 & c0);
            assign cc[4*j+2] = g1 | (p1 & g0) | (p1 & p0 & c0);
            assign cc[4*j+3] = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);
            wire GG = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
            wire PP = p3 & p2 & p1 & p0;
            assign gcarry[j+1] = GG | (PP & c0);
        end
    endgenerate
    assign cla_next = cp ^ cc;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            rca_sum <= rca_next;
            cla_sum <= cla_next;
            armed   <= armed | therm[63];
        end
    end

    assign out = rca_sum;

    always @(posedge clk)
        if (pv && armed && $past(en))
            assert (rca_sum == $past(cla_sum) + {57'd0, $past(cnt)});
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
    wire [2:0] delta = sync1 ^ sync2;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module noc_freq_meter #(
    parameter GATE = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        in_valid,
    output wire        in_ready,
    input  wire        in_edge,
    output reg         out_valid,
    input  wire        out_ready,
    output reg  [31:0] result
);
    reg [31:0] gate_cnt;
    reg [31:0] ev_cnt;
    reg [31:0] gate_snap;
    reg        armed;

    initial begin
        gate_cnt  = 32'd0;
        ev_cnt    = 32'd0;
        gate_snap = 32'd0;
        result    = 32'd0;
        out_valid = 1'b0;
        armed     = 1'b0;
    end

    assign in_ready = !out_valid;
    wire in_fire    = in_valid && in_ready;
    wire out_fire   = out_valid && out_ready;
    wire gate_close = in_fire && (gate_cnt == GATE - 1);

    always @(posedge clk) begin
        if (rst) begin
            gate_cnt  <= 32'd0;
            ev_cnt    <= 32'd0;
            gate_snap <= 32'd0;
            result    <= 32'd0;
            out_valid <= 1'b0;
            armed     <= 1'b0;
        end else begin
            if (in_fire)
                armed <= 1'b1;
            if (in_fire) begin
                if (gate_close) begin
                    gate_cnt  <= 32'd0;
                    ev_cnt    <= 32'd0;
                    result    <= ev_cnt + {31'd0, in_edge};
                    gate_snap <= gate_cnt + 32'd1;
                    out_valid <= 1'b1;
                end else begin
                    gate_cnt <= gate_cnt + 32'd1;
                    ev_cnt   <= ev_cnt + {31'd0, in_edge};
                end
            end else if (out_fire) begin
                out_valid <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && out_valid)
            assert (result <= gate_snap);
endmodule

module acc_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        load,
    input  wire        shift,
    input  wire [63:0] din,
    output wire [63:0] norm_out,
    output wire [6:0]  exp_adj,
    output wire        done
);
    function [6:0] lzc_tree;
        input [63:0] x;
        reg [31:0] y32;
        reg [15:0] y16;
        reg [7:0]  y8;
        reg [3:0]  y4;
        reg [1:0]  y2;
        reg b5, b4, b3, b2, b1, b0;
        begin
            b5  = ~|x[63:32];
            y32 = b5 ? x[31:0] : x[63:32];
            b4  = ~|y32[31:16];
            y16 = b4 ? y32[15:0] : y32[31:16];
            b3  = ~|y16[15:8];
            y8  = b3 ? y16[7:0] : y16[15:8];
            b2  = ~|y8[7:4];
            y4  = b2 ? y8[3:0] : y8[7:4];
            b1  = ~|y4[3:2];
            y2  = b1 ? y4[1:0] : y4[3:2];
            b0  = ~y2[1];
            if (x == 64'd0)
                lzc_tree = 7'd64;
            else
                lzc_tree = {1'b0, b5, b4, b3, b2, b1, b0};
        end
    endfunction

    reg [63:0] data_r;
    reg [6:0]  lz_r;
    reg        armed_r;
    initial data_r  = 64'd0;
    initial lz_r    = 7'd64;
    initial armed_r = 1'b0;

    wire [6:0] lzc_din = lzc_tree(din);
    wire [6:0] lzc_cur = lzc_tree(data_r);

    always @(posedge clk) begin
        if (rst) begin
            data_r  <= 64'd0;
            lz_r    <= 7'd64;
            armed_r <= 1'b0;
        end else if (en) begin
            if (load) begin
                data_r  <= din;
                lz_r    <= lzc_din;
                armed_r <= 1'b1;
            end else if (shift && lz_r != 7'd0 && lz_r != 7'd64) begin
                data_r <= {data_r[62:0], 1'b0};
                lz_r   <= lz_r - 7'd1;
            end
        end
    end

    assign norm_out = data_r;
    assign exp_adj  = lz_r;
    assign done     = (lz_r == 7'd0);

    always @(*) if (armed_r) assert (!(done && !data_r[63]));
    always @(*) if (armed_r) assert (!(data_r[63] && lz_r != 7'd0));
endmodule

module gray_chain_seq (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    output wire o_armed,
    output wire o_started,
    output wire o_done
);
    // three-step chain: arm, start, finish
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_DONE    = 2'd3;

    // gray codes of the milestone binary counts 3, 7 and 12
    localparam [3:0] G_ARM   = 4'b0010; // gray(3)
    localparam [3:0] G_START = 4'b0100; // gray(7)
    localparam [3:0] G_FIN   = 4'b1010; // gray(12)

    reg [3:0] bin;
    reg [3:0] gray;   // gray-code counter, shadowed by bin
    reg [1:0] stage;

    initial bin   = 4'd0;
    initial gray  = 4'd0;
    initial stage = S_IDLE;

    // saturating binary shadow
    wire [3:0] nbin = (bin == 4'd15) ? 4'd15 : (bin + 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            bin   <= 4'd0;
            gray  <= 4'd0;
            stage <= S_IDLE;
        end else if (ce) begin
            bin  <= nbin;
            gray <= nbin ^ (nbin >> 1);
            case (stage)
                S_IDLE:    if (gray == G_ARM)   stage <= S_ARMED;
                S_ARMED:   if (gray == G_START) stage <= S_STARTED;
                S_STARTED: if (gray == G_FIN)   stage <= S_DONE;
                default:                        stage <= S_DONE;
            endcase
        end
    end

    assign o_armed   = (stage != S_IDLE);
    assign o_started = (stage == S_STARTED) || (stage == S_DONE);
    assign o_done    = (stage == S_DONE);

    // P: the finish step can only be observed after the whole chain ran,
    // i.e. the binary shadow must already be past the finish milestone.
    always @(posedge clk)
        if (stage == S_DONE)
            assert (bin >= 4'd12);

endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       wb_pend  = 1'b0;  // writeback slot: entry retired by the head
reg       wb_val   = 1'b0;  // sample value being applied this step
reg       wb_ch    = 1'b0;  // which channel owns the writeback slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
           // ---- writeback slot: applies the entry retired one step ago ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
           // the head hands its entry to the writeback slot; an entry whose
           // sample moved again in the meantime is dropped instead
           wb_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                               && !(cmt_ch == CH_B && b_chg);
           wb_val  <= cmt_val;
           wb_ch   <= cmt_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module axi_burst_to_lite (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_awvalid,
    input  wire [3:0]   i_awid,
    input  wire [31:0]  i_awaddr,
    input  wire [2:0]   i_awlen,
    input  wire         i_wr_en,
    input  wire [2:0]   i_wr_idx,
    input  wire [127:0] i_wr_data,
    input  wire [1:0]   i_lite_bresp,
    input  wire         i_bready,
    output wire         o_awready,
    output wire         o_lite_valid,
    output wire [31:0]  o_lite_awaddr,
    output wire [127:0] o_lite_wdata,
    output wire         o_bvalid,
    output wire [3:0]   o_bid,
    output wire [1:0]   o_bresp
);
    reg         busy = 1'b0;
    reg         bvalid = 1'b0;
    reg         win = 1'b0;
    reg [3:0]   beats_left = 4'd0;
    reg [3:0]   deadline = 4'd0;
    reg [31:0]  addr = 32'd0;
    reg [3:0]   id = 4'd0;
    reg [1:0]   resp_acc = 2'd0;
    reg [2:0]   bidx = 3'd0;
    reg [127:0] wbuf [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            wbuf[i] = 128'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            bvalid <= 1'b0;
            win <= 1'b0;
            beats_left <= 4'd0;
            deadline <= 4'd0;
            addr <= 32'd0;
            id <= 4'd0;
            resp_acc <= 2'd0;
            bidx <= 3'd0;
        end else if (i_ce) begin
            if (!busy && !bvalid && i_awvalid) begin
                busy <= 1'b1;
                win <= 1'b1;
                id <= i_awid;
                addr <= i_awaddr;
                beats_left <= {1'b0, i_awlen} + 4'd1;
                deadline <= {1'b0, i_awlen} + 4'd1;
                resp_acc <= 2'd0;
                bidx <= 3'd0;
            end else if (busy) begin
                beats_left <= beats_left - 4'd1;
                deadline <= deadline - 4'd1;
                addr <= addr + 32'd16;
                bidx <= bidx + 3'd1;
                if (i_lite_bresp > resp_acc)
                    resp_acc <= i_lite_bresp;
                if (beats_left == 4'd1) begin
                    busy <= 1'b0;
                    bvalid <= 1'b1;
                end
            end else if (bvalid && i_bready) begin
                bvalid <= 1'b0;
                win <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (!rst && i_ce && i_wr_en)
            wbuf[i_wr_idx] <= i_wr_data;

    assign o_awready     = !busy && !bvalid;
    assign o_lite_valid  = busy;
    assign o_lite_awaddr = addr;
    assign o_lite_wdata  = wbuf[bidx];
    assign o_bvalid      = bvalid;
    assign o_bid         = id;
    assign o_bresp       = resp_acc;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(beats_left) == 4'd0 || $past(deadline) != 4'd0);
endmodule

module sha2_sched_expander #(
    parameter WIDTH  = 8,
    parameter NW     = 16,
    parameter ROUNDS = 48
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  start,
    input  wire [WIDTH*NW-1:0]   blk,
    output wire [WIDTH-1:0]      o_word,
    output wire                  o_busy,
    output wire                  o_done
);
    localparam [7:0] NR = ROUNDS;

    typedef enum logic [1:0] {IDLE = 2'd0, EXPAND = 2'd1, DONE = 2'd2} state_t;
    state_t state;

    reg [WIDTH*NW-1:0] sched;
    reg [7:0] rnd;
    reg [7:0] tmr;
    reg       win;

    initial begin
        state = IDLE;
        sched = {(WIDTH*NW){1'b0}};
        rnd   = 8'd0;
        tmr   = 8'd0;
        win   = 1'b0;
    end

    function [WIDTH-1:0] rotr(input [WIDTH-1:0] x, input integer n);
        rotr = (x >> n) | (x << (WIDTH - n));
    endfunction

    function [WIDTH-1:0] sig0(input [WIDTH-1:0] x);
        sig0 = rotr(x, 1) ^ rotr(x, 4) ^ (x >> 2);
    endfunction

    function [WIDTH-1:0] sig1(input [WIDTH-1:0] x);
        sig1 = rotr(x, 3) ^ rotr(x, 5) ^ (x >> 1);
    endfunction

    wire [WIDTH-1:0] w0  = sched[0*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w1  = sched[1*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w9  = sched[9*WIDTH  +: WIDTH];
    wire [WIDTH-1:0] w14 = sched[14*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w_new = sig1(w14) + w9 + sig0(w1) + w0;

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                IDLE: begin
                    if (start) begin
                        sched <= blk;
                        rnd   <= 8'd0;
                        tmr   <= NR;
                        state <= EXPAND;
                        win   <= 1'b1;
                    end
                end
                EXPAND: begin
                    sched <= {w_new, sched[WIDTH*NW-1:WIDTH]};
                    rnd   <= rnd + 8'd1;
                    tmr   <= tmr - 8'd1;
                    if (rnd == NR - 8'd1) begin
                        state <= DONE;
                        win   <= 1'b0;
                    end
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    assign o_word = sched[WIDTH*NW-1 -: WIDTH];
    assign o_busy = win;
    assign o_done = (state == DONE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win))
            assert (tmr != 8'd0 && (!$stable(rnd) || $stable(tmr)));
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
  // mixed with the current bin index for a cheap activity signature.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          o_act   <= ce_hist ^ {2'b00, i_bin};
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module lane_deskew4 (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [255:0] din,
    input  wire [3:0]   mk,
    output wire [255:0] dout,
    output wire         aligned_o,
    output wire         timeout_o
);
    reg [63:0] fifo [0:31];
    reg [11:0] wptr;
    reg [11:0] rptr;
    reg [3:0]  seen;
    reg        aligned;
    reg        win;
    reg [63:0] cd;
    reg        timeout;

    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) fifo[k] = 64'd0;
        wptr = 12'd0; rptr = 12'd0; seen = 4'd0;
        aligned = 1'b0; win = 1'b0; cd = 64'd0; timeout = 1'b0;
    end

    wire       q        = !win && !aligned && (|mk);
    wire       force_mk = win && !aligned && (cd == 64'd1);
    wire [3:0] seen_n   = force_mk ? 4'hF : (seen | mk);

    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            wptr <= 12'd0; rptr <= 12'd0; seen <= 4'd0;
            aligned <= 1'b0; win <= 1'b0; cd <= 64'd0; timeout <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 4; i = i + 1) begin
                fifo[i*8 + wptr[i*3 +: 3]] <= din[i*64 +: 64];
                wptr[i*3 +: 3] <= wptr[i*3 +: 3] + 3'd1;
                if (aligned) rptr[i*3 +: 3] <= rptr[i*3 +: 3] + 3'd1;
            end
            seen    <= seen_n;
            timeout <= timeout | (win && !aligned && (cd == 64'd0));
            if (seen_n == 4'hF) begin
                aligned <= 1'b1;
                win     <= 1'b0;
                cd      <= 64'd0;
            end else if (q) begin
                win <= 1'b1;
                cd  <= 64'd8;
            end else if (win && !aligned) begin
                cd <= cd - 64'd1;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : g_out
            assign dout[g*64 +: 64] = fifo[g*8 + rptr[g*3 +: 3]];
        end
    endgenerate

    assign aligned_o = aligned;
    assign timeout_o = timeout;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && !aligned && $stable(aligned))
            assert ($stable(timeout));
endmodule

module mempool_bank_rdata_mux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req_valid,
    input wire [3:0] req_bank,
    input wire [255:0] bank_rdata,
    output reg [15:0] rdata,
    output wire rvalid,
    output wire [15:0] o_rsp_cnt
);
    reg v_q0, v_q1, v_q2;
    reg [3:0] idx_q0, idx_q1, idx_q2;
    reg [15:0] sel_q0, sel_q1, sel_q2;
    reg [15:0] rsp_cnt;

    initial begin
        v_q0 = 1'b0; v_q1 = 1'b0; v_q2 = 1'b0;
        idx_q0 = 4'd0; idx_q1 = 4'd0; idx_q2 = 4'd0;
        sel_q0 = 16'h0000; sel_q1 = 16'h0000; sel_q2 = 16'h0000;
        rsp_cnt = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v_q0 <= 1'b0; v_q1 <= 1'b0; v_q2 <= 1'b0;
            idx_q0 <= 4'd0; idx_q1 <= 4'd0; idx_q2 <= 4'd0;
            sel_q0 <= 16'h0000; sel_q1 <= 16'h0000; sel_q2 <= 16'h0000;
            rsp_cnt <= 16'd0;
        end else if (en) begin
            v_q0 <= req_valid;
            idx_q0 <= req_bank;
            sel_q0 <= req_valid ? (16'h0001 << req_bank) : 16'h0000;
            v_q1 <= v_q0;
            idx_q1 <= idx_q0;
            sel_q1 <= sel_q0;
            v_q2 <= v_q1;
            idx_q2 <= idx_q1;
            sel_q2 <= sel_q1;
            if (v_q2)
                rsp_cnt <= rsp_cnt + 16'd1;
        end
    end

    integer b;
    always @(*) begin
        rdata = 16'h0000;
        for (b = 0; b < 16; b = b + 1)
            if (sel_q2[b])
                rdata = rdata | bank_rdata[b*16 +: 16];
    end

    assign rvalid = v_q2;
    assign o_rsp_cnt = rsp_cnt;

    always @(posedge clk)
        assert ((sel_q2 & (sel_q2 - 16'h0001)) == 16'h0000);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
endmodule

module arrow_bound_cmp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire mode_in,
    input wire [7:0] cnt_in,
    input wire [7:0] len_in,
    output wire o_lt,
    output wire o_eq,
    output wire o_gt
);
    reg mode_r;
    reg [7:0] cnt_r;
    reg [7:0] len_r;
    reg lt_r, eq_r, gt_r;
    reg gt_q;
    initial mode_r = 1'b0;
    initial cnt_r = 8'd0;
    initial len_r = 8'd0;
    initial lt_r = 1'b0;
    initial eq_r = 1'b1;
    initial gt_r = 1'b0;
    initial gt_q = 1'b0;

    wire in_lt = mode_in ? ($signed(cnt_in) < $signed(len_in)) : (cnt_in < len_in);
    wire in_eq = (cnt_in == len_in);
    wire in_gt = !in_lt && !in_eq;

    wire cur_lt = mode_r ? ($signed(cnt_r) < $signed(len_r)) : (cnt_r < len_r);
    wire cur_eq = (cnt_r == len_r);

    wire [7:0] cnt_nx = cnt_r + 8'd1;

    always @(posedge clk) begin
        if (rst) begin
            mode_r <= 1'b0;
            cnt_r <= 8'd0;
            len_r <= 8'd0;
            lt_r <= 1'b0;
            eq_r <= 1'b1;
            gt_r <= 1'b0;
            gt_q <= 1'b0;
        end else if (en) begin
            gt_q <= gt_r;
            if (load) begin
                cnt_r <= cnt_in;
                len_r <= len_in;
                mode_r <= mode_in;
                lt_r <= in_lt;
                eq_r <= in_eq;
                gt_r <= in_gt;
            end else if (eq_r) begin
                eq_r <= 1'b0;
                gt_r <= 1'b1;
            end else if (lt_r) begin
                cnt_r <= cnt_nx;
                if (cnt_nx == len_r) begin
                    lt_r <= 1'b0;
                    eq_r <= 1'b1;
                end
            end
        end
    end

    assign o_lt = lt_r;
    assign o_eq = eq_r;
    assign o_gt = gt_r;

    always @(posedge clk)
        if (gt_r && !gt_q)
            assert (!lt_r && !eq_r);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
output wire [W-1:0] q_mag,
input  wire         peer_in_valid,
output wire         peer_in_ready,
input  wire [W-1:0] peer_in_mag,
output wire         peer_out_valid,
input  wire         peer_out_ready,
output wire [W-1:0] peer_out_min1,
output wire [W-1:0] peer_out_min2,
input  wire         aux_in_valid,
output wire         aux_in_ready,
input  wire [W-1:0] aux_in_mag,
input  wire         aux_in_sign,
output wire         aux_out_valid,
input  wire         aux_out_ready,
output wire [W-1:0] aux_out_min1,
output wire [W-1:0] aux_out_min2,
output wire         aux_out_sign,
output wire [335:0] perf_stats
);
localparam CHANNELS = 3, MINIMA = 2, PEER_CW = (DEG > 1) ? $clog2(DEG) : 1;
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

reg [W-1:0] minima [0:CHANNELS*MINIMA-1];
wire [W-1:0] min1 = minima[0], min2 = minima[1];
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
integer mi;
initial for (mi = 0; mi < CHANNELS*MINIMA; mi = mi + 1) minima[mi] = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
reg [PEER_CW-1:0] peer_count;
reg peer_done;
reg owner_peer;
initial begin peer_count = 0; peer_done = 0; owner_peer = 1; end
reg [PEER_CW-1:0] aux_count;
reg aux_done, aux_owner, aux_sign_prod;
initial begin
    aux_count = 0;
    aux_done = 0;
    aux_owner = 1;
    aux_sign_prod = 0;
end
wire frames_idle = (count == 0) && (peer_count == 0);
wire all_frames_idle = frames_idle && (aux_count == 0);
wire pair_request = (in_valid && state == S_ACCUM) ||
                    (peer_in_valid && !peer_done);
wire select_aux = all_frames_idle ?
    (aux_in_valid && !aux_done && (!pair_request || !aux_owner)) : aux_owner;
wire select_peer = frames_idle ? (peer_in_valid && !peer_done && (!in_valid || state != S_ACCUM || !owner_peer)) : owner_peer;
assign peer_in_ready = select_peer && !peer_done && !select_aux;
assign aux_in_ready = select_aux && !aux_done;
wire peer_acc = peer_in_valid && peer_in_ready;
wire aux_acc = aux_in_valid && aux_in_ready;
wire [W-1:0] cmp_mag = select_aux ? aux_in_mag :
                          (select_peer ? peer_in_mag : in_mag);
wire [W-1:0] cmp_min1 = select_aux ? minima[2*MINIMA] :
                           (select_peer ? minima[MINIMA] : min1);
wire [W-1:0] cmp_min2 = select_aux ? minima[2*MINIMA+1] :
                           (select_peer ? minima[MINIMA+1] : min2);
wire new_first = cmp_mag < cmp_min1;
wire [W-1:0] step_min1 = new_first ? cmp_mag : cmp_min1;
wire [W-1:0] step_min2 = new_first ? cmp_min1 : ((cmp_mag < cmp_min2) ? cmp_mag : cmp_min2);
assign peer_out_valid = peer_done;
assign peer_out_min1 = minima[MINIMA], peer_out_min2 = minima[MINIMA+1];
assign aux_out_valid = aux_done;
assign aux_out_min1 = minima[2*MINIMA];
assign aux_out_min2 = minima[2*MINIMA+1];
assign aux_out_sign = aux_sign_prod;

assign in_ready  = (state == S_ACCUM) && !select_peer && !select_aux;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
wire [CHANNELS-1:0] lane_acc = {aux_acc, peer_acc, acc};
wire [CHANNELS-1:0] lane_rel = {aux_out_valid && aux_out_ready,
                              peer_out_valid && peer_out_ready, rel};
integer lane;
always @(posedge clk) begin
    for (lane = 0; lane < CHANNELS; lane = lane + 1) begin
        if (lane_acc[lane] || lane_rel[lane]) begin
            minima[lane*MINIMA] <= lane_acc[lane] ? step_min1 : {W{1'b1}};
            minima[lane*MINIMA+1] <= lane_acc[lane] ? step_min2 : {W{1'b1}};
        end
    end
    if (acc || peer_acc) owner_peer <= select_peer;
    if (acc || peer_acc || aux_acc) aux_owner <= select_aux;
    if (peer_acc) begin
        if (peer_count == DEG - 1) begin peer_count <= 0; peer_done <= 1; end
        else peer_count <= peer_count + 1'b1;
    end else if (lane_rel[1]) peer_done <= 0;
end
always @(posedge clk) begin
    if (aux_acc) begin
        aux_sign_prod <= aux_sign_prod ^ aux_in_sign;
        if (aux_count == DEG - 1) begin
            aux_count <= 0;
            aux_done <= 1;
        end else begin
            aux_count <= aux_count + 1'b1;
        end
    end else if (lane_rel[2]) begin
        aux_done <= 0;
        aux_sign_prod <= 0;
    end
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;
localparam PERF_CW = 16;
reg [PERF_CW-1:0] perf_accepted [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_completed [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_input_stalls [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_output_stalls [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_stall_run [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_stall_peak [0:CHANNELS-1];
reg [PERF_CW-1:0] perf_busy_cycles [0:CHANNELS-1];
wire [CHANNELS-1:0] perf_input_blocked = {aux_in_valid && !aux_in_ready,
    peer_in_valid && !peer_in_ready,
    in_valid && !in_ready};
wire [CHANNELS-1:0] perf_output_blocked = {aux_out_valid && !aux_out_ready,
    peer_out_valid && !peer_out_ready,
    out_valid && !out_ready};
wire [CHANNELS-1:0] perf_busy = {(aux_count != 0) || aux_done,
    (peer_count != 0) || peer_done,
    (count != 0) || out_valid};
integer perf_init;
initial begin
    for (perf_init = 0; perf_init < CHANNELS; perf_init = perf_init + 1) begin
        perf_accepted[perf_init] = 0;
        perf_completed[perf_init] = 0;
        perf_input_stalls[perf_init] = 0;
        perf_output_stalls[perf_init] = 0;
        perf_stall_run[perf_init] = 0;
        perf_stall_peak[perf_init] = 0;
        perf_busy_cycles[perf_init] = 0;
    end
end
integer perf_lane;
always @(posedge clk) begin
    for (perf_lane = 0; perf_lane < CHANNELS; perf_lane = perf_lane + 1) begin
        if (lane_acc[perf_lane] &&
            perf_accepted[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_accepted[perf_lane] <= perf_accepted[perf_lane] + 1'b1;
        end
        if (lane_rel[perf_lane] &&
            perf_completed[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_completed[perf_lane] <= perf_completed[perf_lane] + 1'b1;
        end
        if (perf_input_blocked[perf_lane] &&
            perf_input_stalls[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_input_stalls[perf_lane] <= perf_input_stalls[perf_lane] + 1'b1;
        end
        if (perf_busy[perf_lane] &&
            perf_busy_cycles[perf_lane] != {PERF_CW{1'b1}}) begin
            perf_busy_cycles[perf_lane] <= perf_busy_cycles[perf_lane] + 1'b1;
        end
        if (perf_output_blocked[perf_lane]) begin
            if (perf_output_stalls[perf_lane] != {PERF_CW{1'b1}}) begin
                perf_output_stalls[perf_lane] <= perf_output_stalls[perf_lane] + 1'b1;
            end
            if (perf_stall_run[perf_lane] != {PERF_CW{1'b1}}) begin
                perf_stall_run[perf_lane] <= perf_stall_run[perf_lane] + 1'b1;
            end
            if (perf_stall_run[perf_lane] >= perf_stall_peak[perf_lane] &&
                perf_stall_run[perf_lane] != {PERF_CW{1'b1}}) begin
                perf_stall_peak[perf_lane] <= perf_stall_run[perf_lane] + 1'b1;
            end
        end else begin
            perf_stall_run[perf_lane] <= 0;
        end
    end
end
genvar perf_g;
generate
    for (perf_g = 0; perf_g < CHANNELS; perf_g = perf_g + 1) begin : gen_perf_export
        assign perf_stats[perf_g*112 + 0 +: PERF_CW] = perf_accepted[perf_g];
        assign perf_stats[perf_g*112 + 16 +: PERF_CW] = perf_completed[perf_g];
        assign perf_stats[perf_g*112 + 32 +: PERF_CW] = perf_input_stalls[perf_g];
        assign perf_stats[perf_g*112 + 48 +: PERF_CW] = perf_output_stalls[perf_g];
        assign perf_stats[perf_g*112 + 64 +: PERF_CW] = perf_stall_run[perf_g];
        assign perf_stats[perf_g*112 + 80 +: PERF_CW] = perf_stall_peak[perf_g];
        assign perf_stats[perf_g*112 + 96 +: PERF_CW] = perf_busy_cycles[perf_g];
    end
endgenerate

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
always @(posedge clk) if (pv) assert ((count == 0) || (peer_count == 0));
always @(posedge clk) if (pv) assert ((aux_count == 0) || ((count == 0) && (peer_count == 0)));
endmodule

module LispDebugBridge (
    input wire clk,
    input wire en,
    input wire start,
    input wire wr_in,
    input wire [3:0] addr_in,
    input wire [63:0] wdata_in,
    output wire busy_o,
    output wire [63:0] rdata_o,
    output wire [63:0] txn_o
);
    // host side
    reg busy = 1'b0;
    reg req_tgl = 1'b0;
    reg ack_s1 = 1'b0;
    reg ack_s2 = 1'b0;
    reg [3:0] addr_q = 4'd0;
    reg wr_q = 1'b0;
    reg [63:0] wdata_q = 64'd0;
    reg [63:0] rdata_q = 64'd0;
    reg [63:0] txn_cnt = 64'd0;
    // core side
    reg req_s1 = 1'b0;
    reg req_s2 = 1'b0;
    reg tgt_seen = 1'b0;
    reg ack_tgl = 1'b0;
    reg [63:0] regs [0:15];
    // verification shadow
    reg [3:0] shadow_addr = 4'd0;
    reg [63:0] shadow_wdata = 64'd0;
    reg win = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            regs[i] = 64'd0;
    end

    wire tgt_fire = (req_s2 != tgt_seen);
    wire launch = start && !busy;

    // host side: launch and completion
    always @(posedge clk) begin
        if (en) begin
            ack_s1 <= ack_tgl;
            ack_s2 <= ack_s1;
            if (launch) begin
                addr_q       <= addr_in;
                wr_q         <= wr_in;
                wdata_q      <= wdata_in;
                req_tgl      <= ~req_tgl;
                busy         <= 1'b1;
                shadow_addr  <= addr_in;
                shadow_wdata <= wdata_in;
                win          <= 1'b1;
            end else if (busy && (ack_s2 == req_tgl)) begin
                busy    <= 1'b0;
                win     <= 1'b0;
                txn_cnt <= txn_cnt + 64'd1;
            end
        end
    end

    // core side: synchronizer and target access
    always @(posedge clk) begin
        if (en) begin
            req_s1 <= req_tgl;
            req_s2 <= req_s1;
            if (tgt_fire) begin
                if (wr_q)
                    regs[addr_q] <= wdata_q;
                else
                    rdata_q <= regs[addr_q];
                tgt_seen <= req_s2;
                ack_tgl  <= ~ack_tgl;
            end
        end
    end

    assign busy_o  = busy;
    assign rdata_o = rdata_q;
    assign txn_o   = txn_cnt;

    // A1: core acts only on the address the host launched
    always @(*) assert (!(win && tgt_fire) || (addr_q == shadow_addr));
    // A2: core writes only the data the host launched
    always @(*) assert (!(win && tgt_fire && wr_q) || (wdata_q == shadow_wdata));
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
,
    output wire [31:0] count_o,
    output wire rd_lap_o,
    output wire [AW-1:0] rptr_o,
    output wire [AW-1:0] wptr_o,
    output wire wr_lap_o
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
    assign count_o = count;
    assign rd_lap_o = rd_lap;
    assign rptr_o = rptr;
    assign wptr_o = wptr;
    assign wr_lap_o = wr_lap;
endmodule

module qp_zins_mux #(
    parameter DEPTH = 16,
    parameter DW = 32,
    parameter SW = $clog2(DEPTH)
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_load,
    input  wire [31:0]   i_limit,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [SW-1:0] in_qp,
    input  wire [DW-1:0] in_data,
    input  wire          i_drain,
    output wire [DW-1:0] o_data,
    output wire          o_valid
,
    output wire [31:0] cnt_o,
    output wire [DEPTH-1:0] mask_o
);
    reg [DEPTH*DW-1:0] data_flat;
    reg [DEPTH-1:0]    mask;
    reg [SW-1:0]       sel;
    reg [31:0]         cnt;
    reg [31:0]         limit;
    reg                win;

    initial data_flat = {(DEPTH*DW){1'b0}};
    initial mask = {DEPTH{1'b0}};
    initial sel = {SW{1'b0}};
    initial cnt = 32'd0;
    initial limit = DEPTH;
    initial win = 1'b0;

    wire hit = mask[sel];
    assign in_ready = !mask[in_qp] && (cnt < limit);
    wire in_fire = in_valid && in_ready;
    wire drn_hit = i_drain && hit;

    wire [DEPTH-1:0] one_m = {{(DEPTH-1){1'b0}}, 1'b1};
    wire [DEPTH-1:0] set_m = in_fire ? (one_m << in_qp) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_m = drn_hit ? (one_m << sel) : {DEPTH{1'b0}};

    // zero-insertion multiplexer: selected slot if valid, else constant zero
    assign o_valid = hit;
    assign o_data  = hit ? data_flat[sel*DW +: DW] : {DW{1'b0}};

    always @(posedge clk) begin
        if (i_reset) begin
            mask  <= {DEPTH{1'b0}};
            sel   <= {SW{1'b0}};
            cnt   <= 32'd0;
            win   <= 1'b0;
            limit <= i_limit;
        end else begin
            if (i_load)
                limit <= i_limit;
            if (in_fire)
                data_flat[in_qp*DW +: DW] <= in_data;
            mask <= (mask & ~clr_m) | set_m;
            cnt  <= cnt + (in_fire ? 32'd1 : 32'd0) - (drn_hit ? 32'd1 : 32'd0);
            if (i_drain)
                sel <= (sel == DEPTH-1) ? {SW{1'b0}} : sel + 1'b1;
            if (i_load)
                win <= 1'b0;
            else if (in_fire)
                win <= 1'b1;
        end
    end

    always @(posedge clk)
        if (win) assert (cnt <= DEPTH);

    always @(posedge clk)
        if (win) assert (cnt != 32'd0 || o_data == {DW{1'b0}});
    assign cnt_o = cnt;
    assign mask_o = mask;
endmodule

module ddr3_qp_window #(
    parameter DW = 32,
    parameter QDEPTH = 4,
    parameter FLIGHT_LIMIT = 8
) (
    input wire clk,
    input wire i_reset,
    input wire in_valid,
    output wire in_ready,
    input wire [DW-1:0] in_data,
    input wire cfg_load,
    input wire [31:0] cfg_wm,
    input wire i_load,
    input wire [31:0] i_limit,
    input wire i_drain,
    output wire [DW-1:0] o_data,
    output wire o_valid,
    output wire almost_full,
    output wire [31:0] occupancy,
    output wire [31:0] a_count_o,
    output wire [3:0] a_rptr_o,
    output wire [3:0] a_wptr_o,
    output wire a_rd_lap_o,
    output wire a_wr_lap_o,
    output wire a_out_valid,
    output wire a_out_ready,
    output wire [DW-1:0] a_out_data,
    output wire [31:0] b_cnt_o,
    output wire [15:0] b_mask_o,
    output reg [$clog2(QDEPTH+1)-1:0] q_count_o,
    output reg [$clog2(QDEPTH)-1:0] q_rptr_o,
    output reg [$clog2(QDEPTH)-1:0] q_wptr_o,
    output reg [$clog2(FLIGHT_LIMIT+1)-1:0] flight_o
);
    localparam A_DEPTH = 12;
    localparam B_DEPTH = 16;
    localparam SW = $clog2(B_DEPTH);
    localparam QAW = $clog2(QDEPTH);
    localparam QCW = $clog2(QDEPTH+1);
    localparam FCW = $clog2(FLIGHT_LIMIT+1);
    localparam [QAW-1:0] QLAST = QDEPTH-1;

    reg [DW-1:0] q_mem [0:QDEPTH-1];
    wire [DW-1:0] q_head = q_mem[q_rptr_o];
    wire [SW-1:0] b_in_qp = q_head[SW-1:0];
    wire b_in_ready;
    wire b_in_valid = !i_reset && (q_count_o != 0);
    wire q_push = a_out_valid && a_out_ready;
    wire q_pop = b_in_valid && b_in_ready;
    wire retire = !i_reset && i_drain && o_valid;

    // Reserve an end-to-end credit until the selected QP is drained.
    assign a_out_ready = !i_reset && (q_count_o < QDEPTH) &&
                         (flight_o < FLIGHT_LIMIT);

    ddr3_cmd_queue #(.DEPTH(A_DEPTH), .DW(DW)) cmd_queue (
        .clk(clk), .in_valid(in_valid), .in_ready(in_ready),
        .in_data(in_data), .out_valid(a_out_valid),
        .out_ready(a_out_ready), .out_data(a_out_data),
        .cfg_load(cfg_load), .cfg_wm(cfg_wm),
        .almost_full(almost_full), .occupancy(occupancy),
        .count_o(a_count_o), .rd_lap_o(a_rd_lap_o),
        .rptr_o(a_rptr_o), .wptr_o(a_wptr_o),
        .wr_lap_o(a_wr_lap_o)
    );

    qp_zins_mux #(.DEPTH(B_DEPTH), .DW(DW), .SW(SW)) qp_mux (
        .clk(clk), .i_reset(i_reset), .i_load(i_load),
        .i_limit(i_limit), .in_valid(b_in_valid),
        .in_ready(b_in_ready), .in_qp(b_in_qp),
        .in_data(q_head), .i_drain(i_drain), .o_data(o_data),
        .o_valid(o_valid), .cnt_o(b_cnt_o), .mask_o(b_mask_o)
    );

    integer j;
    initial begin
        q_count_o = {QCW{1'b0}};
        q_rptr_o = {QAW{1'b0}};
        q_wptr_o = {QAW{1'b0}};
        flight_o = {FCW{1'b0}};
        for (j = 0; j < QDEPTH; j = j + 1)
            q_mem[j] = {DW{1'b0}};
    end

    always @(posedge clk) begin
        if (i_reset) begin
            q_count_o <= {QCW{1'b0}};
            q_rptr_o <= {QAW{1'b0}};
            q_wptr_o <= {QAW{1'b0}};
            flight_o <= {FCW{1'b0}};
            for (j = 0; j < QDEPTH; j = j + 1)
                q_mem[j] <= {DW{1'b0}};
        end else begin
            if (q_push) begin
                q_mem[q_wptr_o] <= a_out_data;
                q_wptr_o <= (q_wptr_o == QLAST) ?
                            {QAW{1'b0}} : q_wptr_o + 1'b1;
            end
            if (q_pop)
                q_rptr_o <= (q_rptr_o == QLAST) ?
                            {QAW{1'b0}} : q_rptr_o + 1'b1;
            case ({q_push, q_pop})
                2'b10: q_count_o <= q_count_o + 1'b1;
                2'b01: q_count_o <= q_count_o - 1'b1;
                default: q_count_o <= q_count_o;
            endcase
            case ({q_push, retire})
                2'b10: flight_o <= flight_o + 1'b1;
                2'b01: flight_o <= flight_o - 1'b1;
                default: flight_o <= flight_o;
            endcase
        end
    end

    always @(posedge clk)
        assert ((q_count_o + b_cnt_o) <= FLIGHT_LIMIT);
endmodule

module dram_init_seq (
    input wire clk,
    input wire rst,
    input wire step,
    input wire rel,
    output reg [2:0] cmd,
    output reg cke,
    output reg init_done
);
    reg [3:0]  cmd_idx  = 4'd0;
    reg [63:0] wait_cnt = 64'd0;
    reg        zq_done  = 1'b0;
    reg        armed    = 1'b0;

    initial cmd = 3'd0;
    initial cke = 1'b0;
    initial init_done = 1'b0;

    function [63:0] cmd_delay;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:    cmd_delay = 64'd4;
                4'd1:    cmd_delay = 64'd3;
                4'd14:   cmd_delay = 64'd4;
                default: cmd_delay = 64'd1;
            endcase
        end
    endfunction

    function [2:0] cmd_code;
        input [3:0] idx;
        begin
            if (idx == 4'd0)       cmd_code = 3'd1;
            else if (idx == 4'd1)  cmd_code = 3'd2;
            else if (idx == 4'd14) cmd_code = 3'd4;
            else if (idx == 4'd15) cmd_code = 3'd0;
            else                   cmd_code = 3'd3;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            cmd_idx   <= 4'd0;
            wait_cnt  <= 64'd0;
            zq_done   <= 1'b0;
            armed     <= 1'b0;
            init_done <= 1'b0;
            cmd       <= 3'd0;
            cke       <= 1'b0;
        end else if (step) begin
            cmd <= 3'd0;
            if (rel) armed <= 1'b0;
            if (wait_cnt != 64'd0) begin
                wait_cnt <= wait_cnt - 64'd1;
            end else if (cmd_idx != 4'd15) begin
                cmd      <= cmd_code(cmd_idx);
                wait_cnt <= cmd_delay(cmd_idx);
                cmd_idx  <= cmd_idx + 4'd1;
                if (cmd_idx == 4'd1) begin
                    cke <= 1'b1;
                    if (!rel) armed <= 1'b1;
                end
                if (cmd_idx == 4'd14) zq_done <= 1'b1;
            end else begin
                init_done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed && init_done)
            assert (zq_done);
endmodule

module jls_pausible_clkctl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire areq,
    input wire mutex_gnt,
    input wire [31:0] din,
    input wire sof,
    input wire eof,
    input wire [7:0] raddr,
    output wire [31:0] dout,
    output wire ring_clk_en
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2;

    reg [1:0] phase = 2'd0;
    reg hs_latch = 1'b0;
    reg clk_en = 1'b1;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    reg [7:0] wptr = 8'd0;
    reg win = 1'b0;
    reg [31:0] linebuf [0:255];

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            linebuf[i] = 32'd0;
    end

    assign dout = linebuf[raddr];
    assign ring_clk_en = clk_en;

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            hs_latch <= 1'b0;
            clk_en <= 1'b1;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
            wptr <= 8'd0;
            win <= 1'b0;
        end else if (en) begin
            if (eof)
                win <= 1'b0;
            else if (sof)
                win <= 1'b1;
            case (phase)
                IDLE: begin
                    if (areq) begin
                        hs_latch <= 1'b1;
                        phase <= ARMED;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                ARMED: begin
                    if (mutex_gnt) begin
                        clk_en <= 1'b0;
                        phase <= STARTED;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                STARTED: begin
                    wptr <= wptr + 8'd1;
                    hs_latch <= 1'b0;
                    clk_en <= 1'b1;
                    phase <= IDLE;
                    fin_cnt <= fin_cnt + 32'd1;
                end
                default: begin
                    phase <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst_n && en && phase == STARTED)
            linebuf[wptr] <= din;
    end

    always @(posedge clk)
        if (win && phase == 2'd2)
            assert (arm_cnt == start_cnt && start_cnt == fin_cnt + 32'd1 && !clk_en);
endmodule

module tc_trace_cache (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [1:0]   op,
    input  wire [3:0]   idx,
    input  wire [31:0]  fill_start,
    input  wire [3:0]   fill_flags,
    input  wire [127:0] fill_instr,
    input  wire [31:0]  fill_next,
    input  wire         trace_begin,
    input  wire         trace_end,
    input  wire [31:0]  fetch_pc,
    output reg          hit,
    output reg  [3:0]   hit_idx,
    output reg  [3:0]   hit_flags,
    output reg  [127:0] hit_instr,
    output reg  [31:0]  hit_next
);
    reg [15:0] valid = 16'h0000;
    reg [31:0] occ   = 32'd0;
    reg        win   = 1'b0;

    reg [31:0] start_addr [0:15];
    reg [3:0]  br_flags   [0:15];
    reg [31:0] slot       [0:63];
    reg [31:0] next_fa    [0:15];

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            start_addr[i] = 32'd0;
            br_flags[i]   = 4'd0;
            next_fa[i]    = 32'd0;
        end
        for (i = 0; i < 64; i = i + 1)
            slot[i] = 32'd0;
    end

    // control state: valid, occupancy, window
    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 16'h0000;
            occ   <= 32'd0;
            win   <= 1'b0;
        end else if (en) begin
            case (op)
                2'd1: begin
                    valid[idx] <= 1'b1;
                    if (!valid[idx]) occ <= occ + 32'd1;
                end
                2'd2: begin
                    valid[idx] <= 1'b0;
                    if (valid[idx]) occ <= occ - 32'd1;
                end
                2'd3: begin
                    valid <= 16'h0000;
                    occ   <= 32'd0;
                end
                default: ;
            endcase
            if (trace_begin)
                win <= 1'b1;
            else if (trace_end || op == 2'd3)
                win <= 1'b0;
        end
    end

    // data storage
    always @(posedge clk) begin
        if (rst_n && en && op == 2'd1) begin
            start_addr[idx]        <= fill_start;
            br_flags[idx]          <= fill_flags;
            next_fa[idx]           <= fill_next;
            slot[{idx, 2'd0}]      <= fill_instr[31:0];
            slot[{idx, 2'd1}]      <= fill_instr[63:32];
            slot[{idx, 2'd2}]      <= fill_instr[95:64];
            slot[{idx, 2'd3}]      <= fill_instr[127:96];
        end
    end

    // combinational lookup
    integer j;
    always @(*) begin
        hit     = 1'b0;
        hit_idx = 4'd0;
        for (j = 15; j >= 0; j = j - 1) begin
            if (valid[j] && start_addr[j] == fetch_pc) begin
                hit     = 1'b1;
                hit_idx = j[3:0];
            end
        end
        hit_flags = br_flags[hit_idx];
        hit_next  = next_fa[hit_idx];
        hit_instr = {slot[{hit_idx, 2'd3}], slot[{hit_idx, 2'd2}],
                     slot[{hit_idx, 2'd1}], slot[{hit_idx, 2'd0}]};
    end

    // properties
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(valid))
            assert ($stable(occ));

    always @(posedge clk)
        if (win)
            assert (occ <= 32'd16);
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
    output wire o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module requant_unit #(
    parameter W  = 64,
    parameter SW = 6
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          arm,
    input  wire          start,
    input  wire          ack,
    input  wire          clr,
    input  wire [W-1:0]  cfg_mult,
    input  wire [SW-1:0] cfg_shift,
    input  wire [W-1:0]  acc_in,
    output reg  [W-1:0]  out_q,
    output reg  [1:0]    phase
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, BUSY = 2'd2, DONE = 2'd3;

    reg [W-1:0]  mult_cfg  = {W{1'b0}};
    reg [SW-1:0] shift_cfg = {SW{1'b0}};
    reg [W-1:0]  work      = {W{1'b0}};
    reg [SW-1:0] cnt       = {SW{1'b0}};
    reg          run       = 1'b0;
    reg          win       = 1'b0;
    initial out_q = {W{1'b0}};
    initial phase = IDLE;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            run   <= 1'b0;
            cnt   <= {SW{1'b0}};
            work  <= {W{1'b0}};
            win   <= 1'b0;
        end else if (ce) begin
            if (clr)
                win <= 1'b0;
            if (phase == IDLE && arm) begin
                mult_cfg  <= cfg_mult;
                shift_cfg <= cfg_shift;
                phase     <= ARMED;
                win       <= 1'b1;
            end
            if (phase == ARMED && start) begin
                work  <= acc_in * mult_cfg;
                cnt   <= shift_cfg;
                run   <= 1'b1;
                phase <= BUSY;
            end
            if (phase == DONE && ack)
                phase <= IDLE;
            if (run) begin
                if (cnt == {SW{1'b0}}) begin
                    out_q <= work;
                    run   <= 1'b0;
                    phase <= DONE;
                end else begin
                    work <= work >> 1;
                    cnt  <= cnt - 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(phase))
            assert ($stable(out_q));
endmodule

module metro_led_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr_en,
    input  wire [5:0]  wr_addr,
    input  wire [63:0] wr_data,
    output wire [63:0] row_drv,
    output wire [63:0] col_drv
);
    reg [63:0] frame_mem_r [0:63];
    reg [63:0] row_idx_r = 64'd0;
    reg [63:0] row_sel_r = 64'h0000_0000_0000_0001;
    reg [63:0] col_r     = 64'd0;
    reg        armed_r   = 1'b0;
    reg        pv_r      = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1)
            frame_mem_r[i] = 64'd0;
    end

    assign row_drv = row_sel_r;
    assign col_drv = col_r;

    always_ff @(posedge clk) begin
        if (wr_en)
            frame_mem_r[wr_addr] <= wr_data;
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_idx_r <= 64'd0;
        else if (en)
            row_idx_r <= (row_idx_r == 64'd63) ? 64'd0 : (row_idx_r + 64'd1);
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_sel_r <= 64'h0000_0000_0000_0001;
        else if (en)
            row_sel_r <= {row_sel_r[62:0], row_sel_r[63]};
    end

    always_ff @(posedge clk) begin
        if (rst)
            col_r <= 64'd0;
        else if (en)
            col_r <= frame_mem_r[row_idx_r[5:0]];
    end

    always_ff @(posedge clk) begin
        if (rst)
            armed_r <= 1'b0;
        else if (en && (row_idx_r == 64'd63))
            armed_r <= 1'b1;
    end

    always_ff @(posedge clk) begin
        pv_r <= 1'b1;
    end

    always @(posedge clk) begin
        if (pv_r && $past(armed_r))
            assert (!($past(row_sel_r[0]) && $past(row_sel_r[63])));
    end
endmodule

module axi_goertzel_bin (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire b_ready,
    input wire clr,
    input wire [15:0] sample,
    input wire [15:0] coef_in,
    output reg done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUNNING = 2'd2, DONE = 2'd3;

    reg [1:0] phase = 2'd0;
    reg signed [15:0] s1 = 16'sd0;
    reg signed [15:0] s2 = 16'sd0;
    reg [15:0] cnt = 16'd0;
    reg [15:0] coef = 16'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg before_clr = 1'b1;
    initial done = 1'b0;

    wire signed [31:0] prod = $signed(coef) * s1;
    wire signed [31:0] fb = prod >>> 14;
    wire signed [15:0] s1_next = $signed(sample) + fb[15:0] - s2;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            s1 <= 16'sd0;
            s2 <= 16'sd0;
            cnt <= 16'd0;
            coef <= 16'd0;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            before_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        coef <= coef_in;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase <= RUNNING;
                        started_seen <= 1'b1;
                        cnt <= 16'd0;
                        s1 <= 16'sd0;
                        s2 <= 16'sd0;
                    end
                end
                RUNNING: begin
                    s1 <= s1_next;
                    s2 <= s1;
                    if (cnt == 16'd23) begin
                        phase <= DONE;
                        done <= 1'b1;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                DONE: begin
                    if (b_ready) begin
                        phase <= IDLE;
                        done <= 1'b0;
                    end
                end
            endcase
            if (clr) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                before_clr <= 1'b0;
            end
        end
    end

    always @(*) assert (!before_clr || !done || (started_seen && armed_seen));
endmodule

module token_chain (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // global enable: low freezes all state
    input  wire i_tick,    // refill timer tick
    input  wire i_arm,     // step 1: arm a transfer request
    input  wire i_start,   // step 2: start it (consumes a token)
    input  wire i_finish,  // step 3: transfer completes
    output wire o_grant,
    output wire o_busy,
    output wire [2:0] o_tokens
);
    localparam [2:0] BURST  = 3'd4;
    localparam [1:0] S_IDLE = 2'd0,
                     S_ARMED= 2'd1,
                     S_RUN  = 2'd2;

    // ---- state ----
    reg [1:0] state;
    reg [2:0] tokens;    // token bucket, capped at BURST
    reg       seen_arm;
    reg       seen_start;
    reg       seen_fin;

    initial state      = S_IDLE;
    initial tokens     = BURST;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial seen_fin   = 1'b0;

    // ---- chain events ----
    wire arm_pulse   = i_ce && !rst && (state == S_IDLE)  && i_arm;
    wire start_pulse = i_ce && !rst && (state == S_ARMED) && i_start && (tokens != 3'd0);
    wire fin_pulse   = i_ce && !rst && (state == S_RUN)   && i_finish;

    // refill on timer tick, never above the burst cap
    wire refill      = i_ce && !rst && i_tick && (tokens < BURST);

    assign o_grant  = start_pulse;
    assign o_busy   = (state == S_RUN);
    assign o_tokens = tokens;

    // ---- three-step request machine ----
    always @(posedge clk)
        if (rst)
            state <= S_IDLE;
        else if (i_ce) begin
            case (state)
                S_IDLE:  if (i_arm)                        state <= S_ARMED;
                S_ARMED: if (i_start && (tokens != 3'd0))  state <= S_RUN;
                S_RUN:   if (i_finish)                     state <= S_IDLE;
                default:                                   state <= S_IDLE;
            endcase
        end

    // ---- token bucket: drains on grant, refills on tick ----
    always @(posedge clk)
        if (rst)
            tokens <= BURST;
        else if (start_pulse && refill)
            tokens <= tokens;
        else if (start_pulse)
            tokens <= tokens - 3'd1;
        else if (refill)
            tokens <= tokens + 3'd1;

    // ---- sticky chain observation bits ----
    always @(posedge clk)
        if (rst) begin
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            seen_fin   <= 1'b0;
        end else begin
            if (arm_pulse)   seen_arm   <= 1'b1;
            if (start_pulse) seen_start <= 1'b1;
            if (fin_pulse)   seen_fin   <= 1'b1;
        end

    // ---- property: a finish is never observed unless arm and start happened ----
    always @(posedge clk)
        if (seen_fin)
            assert (seen_arm && seen_start);
endmodule

module qring_precede (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty,
    output wire [3:0] o_count
);
    parameter CAP = 8;

    // up counter: occupancy.  down counter: free space.  same enable.
    reg [3:0] count;
    reg [3:0] space;
    reg [2:0] wptr, rptr;

    // shadow register: remembers that the queue was already completely full
    reg       ever_full;

    initial count     = 4'd0;
    initial space     = CAP[3:0];
    initial wptr      = 3'd0;
    initial rptr      = 3'd0;
    initial ever_full = 1'b0;

    // flags: fullness is read off the down counter, emptiness off the up counter
    assign o_full  = (space == 4'd0);
    assign o_empty = (count == 4'd0);
    assign o_count = count;

    wire do_push = i_ce && i_push && !o_full;
    wire do_pop  = i_ce && i_pop  && !o_empty;

    wire net_push = do_push && !do_pop;
    wire net_pop  = do_pop  && !do_push;

    always @(posedge i_clk) begin
        if (i_reset) begin
            count <= 4'd0;
            space <= CAP[3:0];
            wptr  <= 3'd0;
            rptr  <= 3'd0;
        end else begin
            if (net_push) begin
                count <= count + 4'd1;
                space <= space - 4'd1;
            end else if (net_pop) begin
                count <= count - 4'd1;
                space <= space + 4'd1;
            end

            if (do_push)
                wptr <= wptr + 3'd1;
            if (do_pop)
                rptr <= rptr + 3'd1;
        end
    end

    // the earlier event: occupancy standing at, or about to reach, capacity
    always @(posedge i_clk) begin
        if (i_reset)
            ever_full <= 1'b0;
        else if ((count == CAP[3:0])
              || (net_push && (count == CAP[3:0] - 4'd1)))
            ever_full <= 1'b1;
    end

    // P: whenever the free-space counter reports the queue full, the fill-up
    //    event must already have been recorded in the shadow register.
    always @(posedge i_clk)
        if (space == 4'd0)
            assert (ever_full);

endmodule

module wc_buffer #(
    parameter LINE_BYTES = 8
) (
    input  wire                      clk,
    input  wire                      in_valid,
    output wire                      in_ready,
    input  wire [63:0]               in_addr,
    input  wire [8*LINE_BYTES-1:0]   in_data,
    input  wire [LINE_BYTES-1:0]     in_be,
    input  wire                      i_flush,
    output wire                      out_valid,
    input  wire                      out_ready,
    output wire [63:0]               out_addr,
    output wire [8*LINE_BYTES-1:0]   out_data,
    output wire [LINE_BYTES-1:0]     out_mask,
    output wire [63:0]               o_bursts
);
    localparam W = 8*LINE_BYTES;
    localparam [LINE_BYTES-1:0] FULL = {LINE_BYTES{1'b1}};

    reg                  buf_valid      = 1'b0;
    reg [63:0]           buf_addr       = 64'd0;
    reg [W-1:0]          buf_data       = {W{1'b0}};
    reg [LINE_BYTES-1:0] buf_mask       = {LINE_BYTES{1'b0}};
    reg [63:0]           buf_cnt        = 64'd0;
    reg                  draining       = 1'b0;
    reg [63:0]           acc_stores     = 64'd0;
    reg [63:0]           flushed_stores = 64'd0;
    reg [63:0]           bursts         = 64'd0;

    wire [W-1:0] be_bits;
    genvar i;
    generate
        for (i = 0; i < LINE_BYTES; i = i + 1) begin : g_be
            assign be_bits[8*i +: 8] = {8{in_be[i]}};
        end
    endgenerate

    wire same_line = buf_valid && (in_addr == buf_addr);
    assign in_ready  = !draining && (!buf_valid || same_line);
    wire in_fire     = in_valid && in_ready;
    assign out_valid = draining;
    wire out_fire    = out_valid && out_ready;

    wire [W-1:0]          base     = buf_valid ? buf_data : {W{1'b0}};
    wire [W-1:0]          merged   = (base & ~be_bits) | (in_data & be_bits);
    wire [LINE_BYTES-1:0] new_mask = (buf_valid ? buf_mask : {LINE_BYTES{1'b0}}) | in_be;

    always @(posedge clk) begin
        if (out_fire) begin
            buf_valid      <= 1'b0;
            buf_mask       <= {LINE_BYTES{1'b0}};
            buf_cnt        <= 64'd0;
            draining       <= 1'b0;
            flushed_stores <= flushed_stores + buf_cnt;
            bursts         <= bursts + 64'd1;
        end else if (in_fire && (in_be != {LINE_BYTES{1'b0}})) begin
            buf_valid  <= 1'b1;
            if (!buf_valid) buf_addr <= in_addr;
            buf_data   <= merged;
            buf_mask   <= new_mask;
            buf_cnt    <= buf_cnt + 64'd1;
            acc_stores <= acc_stores + 64'd1;
            if (new_mask == FULL) draining <= 1'b1;
        end else if (buf_valid && !draining && ((in_valid && !same_line) || i_flush)) begin
            draining <= 1'b1;
        end
    end

    assign out_addr = buf_addr;
    assign out_data = buf_data;
    assign out_mask = buf_mask;
    assign o_bursts = bursts;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(out_valid && out_ready))
            assert (acc_stores == flushed_stores);
endmodule

module comma_align_search #(
    parameter W = 16,
    parameter NOFF = 16,
    parameter [15:0] COMMA = 16'hFA0C
) (
    input  wire clk,
    input  wire rst_n,
    input  wire ce,
    input  wire start,
    input  wire [W-1:0] din,
    output reg  [$clog2(NOFF)-1:0] align_off,
    output reg  locked,
    output reg  searching
);
    localparam OW = $clog2(NOFF);

    reg [W-1:0]  prev_word = {W{1'b0}};
    reg [15:0]   timer     = 16'd0;
    reg [OW-1:0] scan_off  = {OW{1'b0}};
    initial align_off = {OW{1'b0}};
    initial locked    = 1'b0;
    initial searching = 1'b0;

    wire [2*W-1:0] win  = {prev_word, din};
    wire [2*W-1:0] shft = win >> scan_off;
    wire [W-1:0]   cand = shft[W-1:0];
    wire           match = (cand == COMMA);
    wire           expired = (timer == 16'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_word <= {W{1'b0}};
            timer     <= 16'd0;
            scan_off  <= {OW{1'b0}};
            align_off <= {OW{1'b0}};
            locked    <= 1'b0;
            searching <= 1'b0;
        end else if (ce) begin
            prev_word <= din;
            if (!searching) begin
                if (start) begin
                    searching <= 1'b1;
                    locked    <= 1'b0;
                    timer     <= NOFF;
                    scan_off  <= {OW{1'b0}};
                end
            end else begin
                if (match) begin
                    align_off <= scan_off;
                    locked    <= 1'b1;
                    searching <= 1'b0;
                    timer     <= 16'd0;
                    scan_off  <= {OW{1'b0}};
                end else if (scan_off == NOFF - 1) begin
                    searching <= 1'b0;
                    timer     <= 16'd0;
                    scan_off  <= {OW{1'b0}};
                end else begin
                    timer     <= timer - 16'd1;
                    scan_off  <= scan_off + 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(expired)) assert (!searching);
endmodule

module tmr_cred_gate (
    input wire clk,
    input wire step,
    input wire submit,
    input wire logout,
    input wire [7:0] user,
    input wire [7:0] pass,
    output wire grant_admin,
    output wire grant_guest,
    output wire session_armed
);
    localparam [1:0] ROLE_NONE  = 2'b00;
    localparam [1:0] ROLE_GUEST = 2'b01;
    localparam [1:0] ROLE_ADMIN = 2'b10;

    // three shadow copies of the privilege register (TMR)
    reg [1:0] role_a = ROLE_NONE;
    reg [1:0] role_b = ROLE_NONE;
    reg [1:0] role_c = ROLE_NONE;

    // registered grant lines, driven from the voted privilege code
    reg out_admin = 1'b0;
    reg out_guest = 1'b0;

    // sticky arm: set the first time a credential is ever submitted
    reg armed = 1'b0;

    // bitwise 2-of-3 majority voter
    wire [1:0] vote;
    assign vote[1] = (role_a[1] & role_b[1]) | (role_a[1] & role_c[1]) | (role_b[1] & role_c[1]);
    assign vote[0] = (role_a[0] & role_b[0]) | (role_a[0] & role_c[0]) | (role_b[0] & role_c[0]);

    // scrub path: voted value is written back into all three copies
    wire [1:0] scrub = (vote == 2'b11) ? ROLE_NONE : vote;

    // default-credential table lookup
    wire [1:0] lookup = ((user == 8'hAD) && (pass == 8'h1E)) ? ROLE_ADMIN :
                        ((user == 8'h67) && (pass == 8'h00)) ? ROLE_GUEST :
                                                               ROLE_NONE;

    wire [1:0] role_next = logout ? ROLE_NONE : (submit ? lookup : scrub);

    always @(posedge clk) begin
        if (step) begin
            role_a    <= role_next;
            role_b    <= role_next;
            role_c    <= role_next;
            out_admin <= vote[1];
            out_guest <= vote[0];
            if (submit)
                armed <= 1'b1;
        end
    end

    assign grant_admin   = out_admin;
    assign grant_guest   = out_guest;
    assign session_armed = armed;

    // Absence, after Q: once a credential has been submitted, the admin grant
    // and the guest grant are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(grant_admin && grant_guest));
endmodule

module ft60x_axi_default_slave (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire       arvalid,
    input  wire [7:0] arid,
    input  wire [7:0] arlen,
    input  wire       rready,
    input  wire       awvalid,
    input  wire [7:0] awid,
    input  wire       wvalid,
    input  wire       wlast,
    input  wire       bready,
    output wire       arready,
    output wire       rvalid,
    output wire [1:0] rresp,
    output wire       rlast,
    output wire [7:0] rid,
    output wire       awready,
    output wire       wready,
    output wire       bvalid,
    output wire [1:0] bresp,
    output wire [7:0] bid
);
    reg [7:0] rid_q   = 8'd0;
    reg [7:0] len_q   = 8'd0;
    reg [7:0] sent_q  = 8'd0;
    reg       busy    = 1'b0;
    reg       rbeat_q = 1'b0;
    reg       win     = 1'b0;
    reg [7:0] bid_q   = 8'd0;
    reg       wact    = 1'b0;
    reg       bpend   = 1'b0;

    assign arready = en & ~busy;
    assign rvalid  = en & busy;
    assign rresp   = 2'b11;
    assign rlast   = ((sent_q + 8'd1) == len_q);
    assign rid     = rid_q;
    assign awready = en & ~bpend & ~wact;
    assign wready  = en & wact;
    assign bvalid  = en & bpend;
    assign bresp   = 2'b11;
    assign bid     = bid_q;

    wire ar_hs = arvalid & arready;
    wire r_hs  = rvalid & rready;
    wire aw_hs = awvalid & awready;
    wire w_hs  = wvalid & wready;
    wire b_hs  = bvalid & bready;

    always @(posedge clk) begin
        if (!rst_n) begin
            rid_q   <= 8'd0;
            len_q   <= 8'd0;
            sent_q  <= 8'd0;
            busy    <= 1'b0;
            rbeat_q <= 1'b0;
            win     <= 1'b0;
            bid_q   <= 8'd0;
            wact    <= 1'b0;
            bpend   <= 1'b0;
        end else if (en) begin
            rbeat_q <= r_hs;
            if (ar_hs) begin
                rid_q  <= arid;
                len_q  <= ((arlen > 8'd15) ? 8'd15 : arlen) + 8'd1;
                sent_q <= 8'd0;
                busy   <= 1'b1;
                win    <= 1'b1;
            end else if (r_hs) begin
                if (rlast) begin
                    busy   <= 1'b0;
                    sent_q <= 8'd0;
                    win    <= 1'b0;
                end else begin
                    sent_q <= sent_q + 8'd1;
                end
            end
            if (aw_hs) begin
                bid_q <= awid;
                wact  <= 1'b1;
            end
            if (w_hs && wlast) begin
                wact  <= 1'b0;
                bpend <= 1'b1;
            end
            if (b_hs)
                bpend <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && $rose(rbeat_q))
            assert (sent_q <= 8'd16);
endmodule

module thermo_window (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire warmer,
    output reg heat
);
    localparam [3:0] T_LOW  = 4'd4;
    localparam [3:0] T_HIGH = 4'd12;

    reg [3:0] temp;
    reg [1:0] win, heat_cycles, cool_cycles;
    reg cool;                    // second valve position (two-position loop)
    reg cmd_heat, cmd_cool;      // staged window comparator result

    initial begin
        temp = 4'd8; heat = 1'b0;
        win = 2'd0; heat_cycles = 2'd0; cool_cycles = 2'd0;
        cool = 1'b1; cmd_heat = 1'b0; cmd_cool = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            temp <= 4'd8; heat <= 1'b0;
            win <= 2'd0; heat_cycles <= 2'd0; cool_cycles <= 2'd0;
            cool <= 1'b1; cmd_heat <= 1'b0; cmd_cool <= 1'b0;
        end else if (ce) begin
            win <= win + 2'd1;
            if (heat) heat_cycles <= heat_cycles + 2'd1;
            if (cool) cool_cycles <= cool_cycles + 2'd1;
            temp <= warmer ? ((temp == 4'd15) ? temp : temp + 4'd1)
                           : ((temp == 4'd0)  ? temp : temp - 4'd1);
            // apply the command staged on the previous enabled cycle
            if      (cmd_heat) begin heat <= 1'b1; cool <= 1'b0; end
            else if (cmd_cool) begin heat <= 1'b0; cool <= 1'b1; end
            // stage the next command; only the resting position requests a move
            cmd_heat <= cool && (temp <= T_LOW);
            cmd_cool <= heat && (temp >= T_HIGH);
        end
    end

    always @(posedge clk)
        if (cool_cycles == 2'd0)
            assert (heat_cycles == win);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
            end else if (cnt != K) begin
                cnt      <= cnt + 3'd1;
                stable_f <= (cnt == K - 3'd1);
                if (cnt == K - 3'd1)
                    o_clean <= samp;   // commit the debounced value
            end
            // cnt == K: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module hdlbits_cam (
    input wire clk,
    input wire rst,
    input wire en,
    input wire lookup,
    input wire [63:0] lookup_key,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] wr_key,
    output wire hit,
    output wire [1:0] hit_vec
);
    reg [63:0] key_mem [0:1];
    reg [1:0] valid;
    reg s1_vld;
    reg [31:0] s1_key_hi;
    reg [1:0] s1_pm;
    reg s2_vld;
    reg [1:0] s2_match;
    reg [63:0] inflight;
    reg armed;

    initial key_mem[0] = 64'd0;
    initial key_mem[1] = 64'd0;
    initial valid = 2'b00;
    initial s1_vld = 1'b0;
    initial s1_key_hi = 32'd0;
    initial s1_pm = 2'b00;
    initial s2_vld = 1'b0;
    initial s2_match = 2'b00;
    initial inflight = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            key_mem[0] <= 64'd0;
            key_mem[1] <= 64'd0;
            valid <= 2'b00;
            s1_vld <= 1'b0;
            s1_key_hi <= 32'd0;
            s1_pm <= 2'b00;
            s2_vld <= 1'b0;
            s2_match <= 2'b00;
            inflight <= 64'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (wr_en) begin
                key_mem[wr_idx] <= wr_key;
                valid[wr_idx] <= 1'b1;
            end
            s1_vld <= lookup;
            s1_key_hi <= lookup_key[63:32];
            s1_pm[0] <= valid[0] & (key_mem[0][31:0] == lookup_key[31:0]);
            s1_pm[1] <= valid[1] & (key_mem[1][31:0] == lookup_key[31:0]);
            s2_vld <= s1_vld;
            s2_match[0] <= s1_pm[0] & (key_mem[0][63:32] == s1_key_hi);
            s2_match[1] <= s1_pm[1] & (key_mem[1][63:32] == s1_key_hi);
            inflight <= inflight + {63'd0, lookup} - {63'd0, s2_vld};
            armed <= armed | lookup;
        end
    end

    assign hit_vec = s2_vld ? s2_match : 2'b00;
    assign hit = |hit_vec;

    always @(*) assert (!armed || inflight <= 64'd2);
endmodule

